package com.infoviaan.basic.SwitchCase;

public class SwitchVovelOrConconant {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char choice = 'b';
		
		switch (choice) {
		
		case 'a':
			System.out.println("Vovel");
			break;
			
		case 'e':
			System.out.println("Vovel");
			break;
			
		case 'i':
			System.out.println("Vovel");
			break;
			
		case 'o':
			System.out.println("Vovel");
			break;
			
		case 'u':
			System.out.println("Vovel");
			break;
			
		default:
			 System.out.println("Consonant");
		}
	}

}
